mapper.select:
SELECT FAILURE_COUNT, WINDOW_STARTED_AT, LOCKED_UNTIL, EXPIRES_AT
FROM LOGIN_ATTEMPT WHERE ACCOUNT_KEY = #{key}
FOR UPDATE

mapper.update:
UPDATE LOGIN_ATTEMPT
SET FAILURE_COUNT = #{state.failureCount},
    WINDOW_STARTED_AT = #{state.windowStartedAt},
    LOCKED_UNTIL = #{state.lockedUntil,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    EXPIRES_AT = #{state.expiresAt}
WHERE ACCOUNT_KEY = #{key}
